import java.util.Scanner;
public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        Shape[] shapes = new Shape[n];
        for (int i = 0; i < n; i++) {
            String kind = sc.next();
            if (kind.equals("circle")) {
                Circle c = new Circle();
                c.radius = sc.nextDouble();
                shapes[i] = c;
            } else if (kind.equals("square")) {
                Square s = new Square();
                s.side = sc.nextDouble();
                shapes[i] = s;
            } else {
                Rect r = new Rect();
                r.width = sc.nextDouble();
                r.height = sc.nextDouble();
                shapes[i] = r;
            }
        }
        for (int i = 0; i < n; i++) {
            Shape s = shapes[i];
            System.out.printf(s.label() + ": %.2f%n", s.area());
        }
    }
}
abstract class Shape {
    abstract double area();

    abstract String label();
}

class Circle extends Shape {
    double radius;

    @Override
    double area() {
        return Math.PI * radius * radius;
    }

    @Override
    String label() {
        return "Circle";
    }
}

class Square extends Shape {
    double side;

    @Override
    double area() {
        return side * side;
    }

    @Override
    String label() {
        return "Square";
    }
}

class Rect extends Shape {
    double width;
    double height;

    @Override
    double area() {
        return width * height;
    }

    @Override
    String label() {
        return "Rect";
    }
}

import java.util.Scanner;
public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String kind = sc.next();
        int n = sc.nextInt();
        double[] amounts = new double[n];
        for (int i = 0; i < n; i++) {
            amounts[i] = sc.nextDouble();
        }
        double tax = sc.nextDouble();
        Invoice inv;
        if (kind.equals("tax")) {
            TaxInvoice t = new TaxInvoice();
            t.items = amounts;
            t.taxPercent = tax;
            inv = t;
        } else {
            Invoice pl = new Invoice();
            pl.items = amounts;
            inv = pl;
        }
        System.out.printf("Subtotal: %.2f%n", inv.subtotal());
        System.out.printf("Grand total: %.2f%n", inv.total());
    }
}
class Invoice {
    double[] items;

    double subtotal() {
        double s = 0;
        for (double a : items) {
            s += a;
        }
        return s;
    }

    double total() {
        return subtotal();
    }
}

class TaxInvoice extends Invoice {
    double taxPercent;

    double total() {
        double base = super.total();
        return base + base * taxPercent / 100.0;
    }
}

