import java.util.Scanner;
public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String kind = sc.next();
        double value = sc.nextDouble();
        if (kind.equals("circle")) {
            CircleFactory f = new CircleFactory();
            f.radius = value;
            Circle c = f.produce();
            System.out.println("Produced: circle with radius " + c.radius);
            System.out.printf("Area: %.2f%n", c.area());
        } else {
            SquareFactory f = new SquareFactory();
            f.side = value;
            Square s = f.produce();
            System.out.println("Produced: square with side " + s.side);
            System.out.printf("Area: %.2f%n", s.area());
        }
    }
}
class Shape {
    double area() {
        return 0;
    }
}

class Circle extends Shape {
    double radius;

    double area() {
        return Math.PI * radius * radius;
    }
}

class Square extends Shape {
    double side;

    double area() {
        return side * side;
    }
}

class ShapeFactory {
    Shape produce() {
        return new Shape();
    }
}

class CircleFactory extends ShapeFactory {
    double radius;

    Circle produce() {
        Circle c = new Circle();
        c.radius = radius;
        return c;
    }
}

class SquareFactory extends ShapeFactory {
    double side;

    Square produce() {
        Square s = new Square();
        s.side = side;
        return s;
    }
}

