    String text;

    Doc copy() {
        Doc d = new Doc();
        d.text = text;
        return d;
    }
}

class Report extends Doc {
    String author;

    Report copy() {
        Report r = new Report();
        r.text = text;
        r.author = author;
        return r;
    }
}

